-- SmartFamily 0.9.0 - row-level security with sharing between families (GENERATED by scripts/gen_tables.py).
-- Run after 0009_a_sharing.sql. Safe to run again.
-- Each table keeps its own rule and also allows access granted by an accepted share from another family.

do $$
declare r record; rd text; wr text; base text;
begin
  for r in select * from (values
    ('chores', '''chores''', 'id', '', 'public.sf_my_role(family_id) in (''OWNER'',''ADMIN'',''MEMBER'')', ''),
    ('chore_completions', '''chores''', 'chore_id', '', 'public.sf_my_role(family_id) in (''OWNER'',''ADMIN'',''MEMBER'',''CHILD'')', ''),
    ('points_entries', '''chores''', 'null', '', 'public.sf_my_role(family_id) in (''OWNER'',''ADMIN'',''MEMBER'')', ''),
    ('rewards', '''chores''', 'null', '', 'public.sf_my_role(family_id) in (''OWNER'',''ADMIN'',''MEMBER'')', ''),
    ('family_dates', '''calendar''', 'id', '', 'public.sf_my_role(family_id) in (''OWNER'',''ADMIN'',''MEMBER'')', ''),
    ('events', '''calendar''', 'id', '', 'public.sf_my_role(family_id) in (''OWNER'',''ADMIN'',''MEMBER'')', ''),
    ('recipes', '''recipes''', 'id', '', 'public.sf_my_role(family_id) in (''OWNER'',''ADMIN'',''MEMBER'')', ''),
    ('recipe_ratings', '''recipes''', 'recipe_id', '', 'public.sf_my_role(family_id) in (''OWNER'',''ADMIN'',''MEMBER'',''CHILD'')', ''),
    ('meal_plan_entries', '''recipes''', 'null', '', 'public.sf_my_role(family_id) in (''OWNER'',''ADMIN'',''MEMBER'')', ''),
    ('meal_profiles', '''packed_meals''', 'id', '', 'public.sf_my_role(family_id) in (''OWNER'',''ADMIN'',''MEMBER'')', ''),
    ('packed_meals', '''packed_meals''', 'profile_id', '', 'public.sf_my_role(family_id) in (''OWNER'',''ADMIN'',''MEMBER'',''CHILD'')', ''),
    ('appliances', '''appliances''', 'id', '', 'public.sf_my_role(family_id) in (''OWNER'',''ADMIN'',''MEMBER'')', ''),
    ('laundry_presets', '''appliances''', 'appliance_id', '', 'public.sf_my_role(family_id) in (''OWNER'',''ADMIN'',''MEMBER'')', ''),
    ('chats', '''chat''', 'id', 'id', 'public.sf_my_role(family_id) in (''OWNER'',''ADMIN'',''MEMBER'',''CHILD'')', ''),
    ('chat_keys', '''chat''', 'chat_id', 'chat_id', 'public.sf_my_role(family_id) in (''OWNER'',''ADMIN'',''MEMBER'',''CHILD'')', ''),
    ('chat_messages', '''chat''', 'chat_id', 'chat_id', '', 'sender_id'),
    ('chat_reactions', '''chat''', 'chat_id', 'chat_id', '', 'user_id'),
    ('chat_reads', '''chat''', 'chat_id', 'chat_id', '', 'user_id'),
    ('trips', '''travel''', 'id', '', 'public.sf_my_role(family_id) in (''OWNER'',''ADMIN'',''MEMBER'')', ''),
    ('trip_items', '''travel''', 'trip_id', '', 'public.sf_my_role(family_id) in (''OWNER'',''ADMIN'',''MEMBER'',''CHILD'')', ''),
    ('budget_entries', '''budget''', 'null', '', 'public.sf_my_role(family_id) in (''OWNER'',''ADMIN'',''MEMBER'')', ''),
    ('budget_limits', '''budget''', 'null', '', 'public.sf_my_role(family_id) in (''OWNER'',''ADMIN'',''MEMBER'')', ''),
    ('home_entries', 'case when section = ''KNOWLEDGE'' then ''knowledge'' else ''home_book'' end', 'id', '', 'public.sf_my_role(family_id) in (''OWNER'',''ADMIN'',''MEMBER'')', ''),
    ('polls', '''polls''', 'id', '', 'public.sf_my_role(family_id) in (''OWNER'',''ADMIN'',''MEMBER'',''CHILD'')', ''),
    ('poll_votes', '''polls''', 'poll_id', '', '', 'user_id'),
    ('recurring_payments', '''budget''', 'null', '', 'public.sf_my_role(family_id) in (''OWNER'',''ADMIN'',''MEMBER'')', ''),
    ('pocket_entries', '''budget''', 'null', '', 'public.sf_my_role(family_id) in (''OWNER'',''ADMIN'',''MEMBER'')', ''),
    ('goals', '''budget''', 'id', '', 'public.sf_my_role(family_id) in (''OWNER'',''ADMIN'',''MEMBER'')', ''),
    ('split_expenses', '''budget''', 'id', '', 'public.sf_my_role(family_id) in (''OWNER'',''ADMIN'',''MEMBER'',''CHILD'')', ''),
    ('growth_entries', '''chores''', 'null', '', 'public.sf_my_role(family_id) in (''OWNER'',''ADMIN'',''MEMBER'')', ''),
    ('repairs', '''home_book''', 'id', '', 'public.sf_my_role(family_id) in (''OWNER'',''ADMIN'',''MEMBER'')', ''),
    ('meter_readings', '''home_book''', 'null', '', 'public.sf_my_role(family_id) in (''OWNER'',''ADMIN'',''MEMBER'')', ''),
    ('kit_items', '''travel''', 'null', '', 'public.sf_my_role(family_id) in (''OWNER'',''ADMIN'',''MEMBER'',''CHILD'')', ''),
    ('routine_steps', '''chores''', 'null', '', 'public.sf_my_role(family_id) in (''OWNER'',''ADMIN'',''MEMBER'')', ''),
    ('routine_checks', '''chores''', 'null', '', 'public.sf_my_role(family_id) in (''OWNER'',''ADMIN'',''MEMBER'',''CHILD'')', ''),
    ('tree_people', '''calendar''', 'null', '', 'public.sf_my_role(family_id) in (''OWNER'',''ADMIN'',''MEMBER'')', '')
  ) as v(tn, modx, item, guard, w, owner) loop
    rd := format('public.sf_shared(family_id, %s, %s, false)', r.modx, r.item);
    wr := format('public.sf_shared(family_id, %s, %s, true)', r.modx, r.item);
    if r.guard <> '' then
      rd := rd || format(' and public.sf_chat_member(%s)', r.guard);
      wr := wr || format(' and public.sf_chat_member(%s)', r.guard);
    end if;
    if r.owner <> '' then
      base := format('(public.sf_is_member(family_id) or %s) and %s = auth.uid()::text', wr, r.owner);
    else
      base := format('(%s) or (%s)', r.w, wr);
    end if;
    execute format('drop policy if exists %1$s_select on public.%1$s', r.tn);
    execute format('create policy %1$s_select on public.%1$s for select to authenticated using (public.sf_is_member(family_id) or (%2$s))', r.tn, rd);
    execute format('drop policy if exists %1$s_insert on public.%1$s', r.tn);
    execute format('create policy %1$s_insert on public.%1$s for insert to authenticated with check (%2$s)', r.tn, base);
    execute format('drop policy if exists %1$s_update on public.%1$s', r.tn);
    execute format('create policy %1$s_update on public.%1$s for update to authenticated using (%2$s) with check (%2$s)', r.tn, base);
  end loop;
end $$;
